/**
 * Quiet Command Center application shell. Every status shown here is fetched from
 * protected Next.js APIs backed by MongoDB; empty states deliberately contain no demo data.
 */
"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { Bell, CalendarCheck2, Check, CheckCircle2, ChevronRight, ClipboardList, Clock3, Crown, LayoutGrid, LoaderCircle, Plus, Send, ShieldCheck, UsersRound, X } from "lucide-react";
import { LogoutButton } from "@/components/auth/logout-button";
import { EmployeeDetailCanvas } from "@/components/workspace/employee-detail-canvas";
import { AccessControlPanel, TeamStatusCanvas } from "@/components/workspace/team-management";
import { getRefreshStatus } from "@/lib/refresh-status";

type Role = "developer" | "manager" | "admin";
type User = { id: string; email: string; displayName: string | null; photoUrl: string | null; role: Role; isActive: boolean; createdAt: string; lastSignedInAt: string };
type Attendance = { id: string; userId: string; workDate: string; punchInAt: string; punchOutAt?: string; classification: "on_time" | "late"; state: "working" | "punched_out"; device: { ipAddress: string | null; userAgent: string | null } };
type WorkUpdate = { id: string; userId: string; updateDate: string; tasks: { id: string; description: string; minutes: number }[]; totalMinutes: number; blockers: string | null; submittedAt: string; updatedAt: string };
type AssignedTask = { id: string; developerUserId: string; assignedByUserId: string; description: string; status: "pending" | "completed"; assignedAt: string; completedAt: string | null; remarks: { id: string; userName: string; text: string; createdAt: string }[] };
type Notification = { id: string; title: string; body: string; isRead: boolean; createdAt: string; type: string };
type TeamMember = { user: User; update: WorkUpdate | null };
type Tab = "my-updates" | "team-updates" | "attendance" | "roles";

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(path, { credentials: "include", headers: { "Content-Type": "application/json", ...(init?.headers || {}) }, ...init });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || "The request failed.");
  return data as T;
}

function duration(minutes: number) { return minutes >= 60 ? `${Math.floor(minutes / 60)}h ${minutes % 60 ? `${minutes % 60}m` : ""}`.trim() : `${minutes}m`; }
const displayDateFormat = new Intl.DateTimeFormat("en-GB", { day: "2-digit", month: "short", year: "numeric", timeZone: "UTC" });
const displayTimeFormat = new Intl.DateTimeFormat("en-GB", { hour: "2-digit", minute: "2-digit", hour12: true, timeZone: "Asia/Kolkata" });
function formatTime(value?: string) { return value ? displayTimeFormat.format(new Date(value)) : "—"; }
function formatDate(value: string) { return displayDateFormat.format(new Date(`${value}T12:00:00Z`)); }
function initials(name: string | null, email: string) { return (name || email).split(" ").map((part) => part[0]).join("").slice(0, 2).toUpperCase(); }

export function DevSyncWorkspace({ user, businessDate, initialAdminEmail }: { user: User; businessDate: string; initialAdminEmail: string }) {
  const [activeTab, setActiveTab] = useState<Tab>("my-updates");
  const [attendance, setAttendance] = useState<Attendance | null>(null);
  const [updates, setUpdates] = useState<WorkUpdate[]>([]);
  const [tasks, setTasks] = useState<AssignedTask[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [allUsers, setAllUsers] = useState<User[]>([user]);
  const [isBusy, setIsBusy] = useState(false);
  const [draftTasks, setDraftTasks] = useState([{ id: "first-task", description: "", minutes: "0" }]);
  const [blockers, setBlockers] = useState("");
  const [workDate, setWorkDate] = useState(businessDate);
  const [remarkText, setRemarkText] = useState<Record<string, string>>({});
  const [clientReady, setClientReady] = useState(false);
  const [lastRefreshedAt, setLastRefreshedAt] = useState<string | null>(null);
  const [isRefreshing, setIsRefreshing] = useState(true);
  const [selectedEmployeeId, setSelectedEmployeeId] = useState<string | null>(null);

  const canViewTeam = user.role === "admin" || user.role === "manager";
  const unreadCount = notifications.filter((notification) => !notification.isRead).length;
  const firstName = user.displayName?.split(" ")[0] || user.email.split("@")[0];

  const reloadCore = useCallback(async () => {
    setError(null);
    setIsRefreshing(true);
    try {
      const [attendanceResult, updateResult, taskResult, notificationResult] = await Promise.all([
        request<{ attendance: Attendance | null }>(`/api/attendance?workDate=${businessDate}`),
        request<{ updates: WorkUpdate[] }>("/api/work-updates"),
        request<{ tasks: AssignedTask[] }>("/api/tasks"),
        request<{ notifications: Notification[] }>("/api/notifications"),
      ]);
      setAttendance(attendanceResult.attendance); setUpdates(updateResult.updates); setTasks(taskResult.tasks); setNotifications(notificationResult.notifications); setLastRefreshedAt(new Date().toISOString());
    } catch (loadError) { setError(loadError instanceof Error ? loadError.message : "Unable to load workspace data."); }
    finally { setIsLoading(false); setIsRefreshing(false); }
  }, [businessDate]);

  const loadTeam = useCallback(async () => {
    if (!canViewTeam) return;
    try {
      const result = await request<{ members: TeamMember[] }>(`/api/team-updates?workDate=${workDate}`);
      setTeamMembers(result.members);
    } catch (loadError) { setError(loadError instanceof Error ? loadError.message : "Unable to load team status."); }
  }, [canViewTeam, workDate]);

  const loadUsers = useCallback(async () => {
    if (user.role !== "admin") return;
    try { setAllUsers((await request<{ users: User[] }>("/api/admin/users")).users); }
    catch (loadError) { setError(loadError instanceof Error ? loadError.message : "Unable to load users."); }
  }, [user.role]);

  useEffect(() => { void reloadCore(); }, [reloadCore]);
  useEffect(() => { setClientReady(true); }, []);
  useEffect(() => { if (activeTab === "team-updates") void loadTeam(); }, [activeTab, loadTeam]);
  useEffect(() => { if (activeTab === "roles") void loadUsers(); }, [activeTab, loadUsers]);
  useEffect(() => { const timer = window.setInterval(() => { void reloadCore(); if (activeTab === "team-updates") void loadTeam(); if (activeTab === "roles") void loadUsers(); }, 15_000); return () => window.clearInterval(timer); }, [activeTab, loadTeam, loadUsers, reloadCore]);

  const selectedUpdate = useMemo(() => updates.find((update) => update.updateDate === workDate) || null, [updates, workDate]);

  async function perform(action: () => Promise<void>) {
    setIsBusy(true); setError(null);
    try { await action(); await reloadCore(); if (activeTab === "team-updates") await loadTeam(); if (activeTab === "roles") await loadUsers(); }
    catch (actionError) { setError(actionError instanceof Error ? actionError.message : "Action failed."); }
    finally { setIsBusy(false); }
  }

  function punch(action: "punch_in" | "punch_out") { return perform(async () => { await request("/api/attendance", { method: "POST", body: JSON.stringify({ action }) }); }); }
  function completeAssignedTask(taskId: string) { return perform(async () => { await request(`/api/tasks/${taskId}`, { method: "PATCH" }); }); }
  function submitUpdate() {
    return perform(async () => {
      await request("/api/work-updates", { method: "POST", body: JSON.stringify({ updateDate: workDate, tasks: draftTasks.map((task) => ({ id: task.id, description: task.description, minutes: Number(task.minutes) })), blockers: blockers || null }) });
      setDraftTasks([{ id: crypto.randomUUID(), description: "", minutes: "0" }]); setBlockers("");
    });
  }
  function addRemark(taskId: string) { return perform(async () => { await request(`/api/tasks/${taskId}/remarks`, { method: "POST", body: JSON.stringify({ text: remarkText[taskId] || "" }) }); setRemarkText((current) => ({ ...current, [taskId]: "" })); }); }
  function changeRole(targetUserId: string, role: Role) { return perform(async () => { await request(`/api/admin/users/${targetUserId}/role`, { method: "PATCH", body: JSON.stringify({ role }) }); }); }
  async function changeActivity(targetUserId: string, isActive: boolean) {
    await request(`/api/admin/users/${targetUserId}/activity`, { method: "PATCH", body: JSON.stringify({ isActive }) });
    await Promise.all([reloadCore(), loadTeam(), loadUsers()]);
  }
  async function deleteEmployee(targetUserId: string) {
    await request(`/api/admin/users/${targetUserId}`, { method: "DELETE" });
    setSelectedEmployeeId((current) => current === targetUserId ? null : current);
    await Promise.all([reloadCore(), loadTeam(), loadUsers()]);
  }
  function markRead(notificationId?: string) { return perform(async () => { await request("/api/notifications", { method: "PATCH", body: JSON.stringify(notificationId ? { notificationId } : {}) }); }); }

  const tabs: { id: Tab; label: string; icon: typeof ClipboardList; visible: boolean }[] = [
    { id: "my-updates", label: "My updates", icon: ClipboardList, visible: true },
    { id: "team-updates", label: "Team updates", icon: UsersRound, visible: canViewTeam },
    { id: "attendance", label: "Attendance", icon: CalendarCheck2, visible: true },
    { id: "roles", label: "Role management", icon: Crown, visible: user.role === "admin" },
  ];

  return (
    <main className="min-h-screen bg-[#F6F8FB] text-[#173247]">
      <header className="sticky top-0 z-30 border-b border-[#E3EBEF] bg-white/95 backdrop-blur"><div className="mx-auto flex h-16 max-w-[1440px] items-center justify-between gap-4 px-4 sm:px-7"><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#173247] text-xs font-black text-[#69D4C4]">D</span><div><p className="font-display text-lg font-extrabold tracking-[-0.055em]">devsync</p><p className="-mt-0.5 text-[8px] font-extrabold uppercase tracking-[0.15em] text-[#7890A0]">daily operating system</p></div></div><div className="flex items-center gap-1 sm:gap-3"><button type="button" aria-label="Open notifications" onClick={() => setIsDrawerOpen((open) => !open)} className="relative flex h-9 w-9 items-center justify-center rounded-lg text-[#6A8191] transition hover:bg-[#EEF5F5] hover:text-[#0E9384]"><Bell className="h-4 w-4" />{unreadCount > 0 && <span className="absolute right-1 top-1 min-w-4 rounded-full bg-[#0E9384] px-1 text-[9px] font-black leading-4 text-white">{unreadCount}</span>}</button><div className="hidden items-center gap-2 border-l border-[#E7EEF1] pl-3 sm:flex"><span className="flex h-7 w-7 items-center justify-center rounded-full bg-[#EAF7F4] text-[10px] font-extrabold text-[#087A6D]">{initials(user.displayName, user.email)}</span><span className="max-w-28 truncate text-xs font-extrabold">{user.displayName || user.email}</span></div><LogoutButton /></div></div></header>
      <div className="mx-auto grid max-w-[1440px] lg:grid-cols-[220px_1fr]"><aside className="border-b border-[#E3EBEF] bg-white p-3 lg:min-h-[calc(100vh-4rem)] lg:border-b-0 lg:border-r lg:p-5"><nav className="flex gap-1 overflow-x-auto lg:flex-col">{tabs.filter((tab) => tab.visible).map(({ id, label, icon: Icon }) => <button key={id} type="button" onClick={() => setActiveTab(id)} className={`flex shrink-0 items-center gap-2.5 rounded-xl px-3 py-2.5 text-xs font-extrabold transition ${activeTab === id ? "bg-[#EAF7F4] text-[#087A6D]" : "text-[#688091] hover:bg-[#F3F7F8] hover:text-[#173247]"}`}><Icon className="h-4 w-4" />{label}</button>)}</nav><div className="mt-5 hidden rounded-xl border border-[#DDEBE8] bg-[#F5FBF9] p-3 lg:block"><p className="text-[9px] font-extrabold uppercase tracking-[0.12em] text-[#0E9384]">Active account</p><p className="mt-2 truncate text-xs font-extrabold">{user.email}</p><span className="mt-2 inline-flex rounded-full bg-white px-2 py-1 text-[9px] font-extrabold uppercase tracking-[0.1em] text-[#0E9384]">{user.role}</span><p className="mt-2 text-[9px] font-bold text-[#7890A0]">Workspace {clientReady ? "live" : "connecting"}</p></div></aside>
        <section className="min-w-0 p-4 sm:p-7"><div className="mb-6 flex flex-wrap items-end justify-between gap-3"><div><p className="text-[10px] font-extrabold uppercase tracking-[0.16em] text-[#0E9384]">{formatDate(businessDate)}</p><h1 className="mt-1 font-display text-3xl font-extrabold tracking-[-0.06em] sm:text-4xl">{selectedEmployeeId ? "Employee operations" : activeTab === "my-updates" ? `Good day, ${firstName}.` : activeTab === "team-updates" ? "Daily team status" : activeTab === "attendance" ? "Attendance ledger" : "Manage team roles"}</h1></div>{!selectedEmployeeId && activeTab !== "roles" && <AttendancePill attendance={attendance} isBusy={isBusy} onPunch={punch} />}</div>
          <p aria-live="polite" className="-mt-3 mb-5 text-[10px] font-bold uppercase tracking-[0.1em] text-[#7890A0]">{getRefreshStatus(lastRefreshedAt, isRefreshing)}</p>
          {error && <div role="alert" className="mb-5 flex items-start gap-3 rounded-xl border border-[#F4C9C4] bg-[#FFF5F4] px-4 py-3 text-xs font-semibold text-[#A64D43]"><X className="mt-0.5 h-4 w-4 shrink-0" />{error}</div>}
          {selectedEmployeeId ? <EmployeeDetailCanvas employeeId={selectedEmployeeId} viewerRole={user.role} onBack={() => setSelectedEmployeeId(null)} onChanged={() => { void reloadCore(); void loadTeam(); void loadUsers(); }} /> : isLoading ? <LoadingState /> : activeTab === "my-updates" ? <MyUpdatesV2 attendance={attendance} businessDate={businessDate} workDate={workDate} setWorkDate={setWorkDate} update={selectedUpdate} updates={updates} tasks={tasks} draftTasks={draftTasks} blockers={blockers} remarkText={remarkText} isBusy={isBusy} onDraftTasks={setDraftTasks} onBlockers={setBlockers} onRemarkText={setRemarkText} onSubmit={submitUpdate} onComplete={completeAssignedTask} onAddRemark={addRemark} /> : activeTab === "team-updates" ? <TeamStatusCanvas workDate={workDate} setWorkDate={setWorkDate} members={teamMembers} onOpenEmployee={setSelectedEmployeeId} onAssigned={() => { void reloadCore(); void loadTeam(); }} /> : activeTab === "attendance" ? <AttendanceModule attendance={attendance} businessDate={businessDate} canViewTeam={canViewTeam} /> : <AccessControlPanel users={allUsers} selfId={user.id} initialAdminEmail={initialAdminEmail} isBusy={isBusy} onChangeRole={changeRole} onChangeActivity={changeActivity} onDelete={deleteEmployee} />}
        </section>
      </div>
      {isDrawerOpen && <NotificationDrawer notifications={notifications} onClose={() => setIsDrawerOpen(false)} onMarkRead={markRead} />}
    </main>
  );
}

function AttendancePill({ attendance, isBusy, onPunch }: { attendance: Attendance | null; isBusy: boolean; onPunch: (action: "punch_in" | "punch_out") => void }) {
  const buttonLabel = !attendance ? "Punch in" : attendance.state === "working" ? "Punch out" : "Day closed";
  const isActionable = !attendance || attendance.state === "working";
  return <div className={`flex items-center gap-3 rounded-xl border p-2 shadow-sm ${isActionable ? "border-[#F3C4C0] bg-[#FFF7F6]" : "border-[#E8D3D1] bg-[#FFF9F8]"}`}><div className="hidden sm:block"><p className="text-[9px] font-extrabold uppercase tracking-[0.12em] text-[#B42318]">Today</p><p className="mt-0.5 text-xs font-extrabold text-[#8F2118]">{attendance ? `${attendance.classification === "on_time" ? "On time" : "Late"} · ${attendance.state === "working" ? "Working" : "Punched out"}` : "Not punched in"}</p></div><button disabled={isBusy || attendance?.state === "punched_out"} onClick={() => onPunch(attendance?.state === "working" ? "punch_out" : "punch_in")} className={`rounded-lg px-3 py-2 text-xs font-extrabold text-white shadow-[0_5px_14px_rgba(217,45,32,0.2)] transition active:scale-[0.98] ${isActionable ? "bg-[#D92D20] hover:bg-[#B42318]" : "bg-[#B42318] shadow-none"} disabled:cursor-not-allowed disabled:opacity-80`}>{isBusy ? <LoaderCircle className="h-4 w-4 animate-spin" /> : buttonLabel}</button></div>;
}

function MyUpdates({ attendance, businessDate, updateToday, updates, tasks, taskDescription, taskMinutes, blockers, isBusy, onTaskDescription, onTaskMinutes, onBlockers, onSubmit, onComplete }: { attendance: Attendance | null; businessDate: string; updateToday: WorkUpdate | null; updates: WorkUpdate[]; tasks: AssignedTask[]; taskDescription: string; taskMinutes: string; blockers: string; isBusy: boolean; onTaskDescription: (value: string) => void; onTaskMinutes: (value: string) => void; onBlockers: (value: string) => void; onSubmit: () => void; onComplete: (id: string) => void }) {
  const canSubmit = Boolean(attendance && taskDescription.trim() && Number(taskMinutes) >= 0 && !isBusy);
  return <div className="grid gap-5 xl:grid-cols-[1.1fr_0.9fr]"><div className="space-y-5"><section className="rounded-2xl border border-[#E1EAED] bg-white p-5 shadow-sm"><div className="flex items-start justify-between gap-3"><div><p className="text-[10px] font-extrabold uppercase tracking-[0.15em] text-[#0E9384]">Daily work update</p><h2 className="mt-1 text-lg font-extrabold">{updateToday ? "Update today’s progress" : "Log what you completed"}</h2></div><span className="rounded-full bg-[#F3F7F8] px-2.5 py-1 text-[10px] font-extrabold text-[#658092]">{formatDate(businessDate)}</span></div>{!attendance && <div className="mt-4 rounded-xl border border-[#F2DFC0] bg-[#FFF9EF] px-3 py-2.5 text-xs font-semibold text-[#946D2B]">Punch In Required — you must punch in before adding a work update.</div>}<div className="mt-5 grid gap-3 sm:grid-cols-[1fr_110px]"><label className="block"><span className="mb-1.5 block text-[10px] font-extrabold uppercase tracking-[0.11em] text-[#7890A0]">Task completed</span><input value={taskDescription} onChange={(event) => onTaskDescription(event.target.value)} placeholder="What did you complete?" className="w-full rounded-xl border border-[#DDE7EB] px-3 py-2.5 text-sm font-semibold outline-none transition placeholder:text-[#A4B1BA] focus:border-[#0E9384] focus:ring-4 focus:ring-[#0E9384]/10" /></label><label className="block"><span className="mb-1.5 block text-[10px] font-extrabold uppercase tracking-[0.11em] text-[#7890A0]">Minutes</span><input value={taskMinutes} onChange={(event) => onTaskMinutes(event.target.value.replace(/[^0-9]/g, ""))} inputMode="numeric" className="w-full rounded-xl border border-[#DDE7EB] px-3 py-2.5 text-sm font-semibold outline-none transition focus:border-[#0E9384] focus:ring-4 focus:ring-[#0E9384]/10" /></label></div><label className="mt-3 block"><span className="mb-1.5 block text-[10px] font-extrabold uppercase tracking-[0.11em] text-[#7890A0]">Blockers / notes <span className="normal-case tracking-normal">(optional)</span></span><textarea value={blockers} onChange={(event) => onBlockers(event.target.value)} placeholder="Any issue your manager should know?" rows={3} className="w-full resize-none rounded-xl border border-[#DDE7EB] px-3 py-2.5 text-sm font-medium outline-none transition placeholder:text-[#A4B1BA] focus:border-[#0E9384] focus:ring-4 focus:ring-[#0E9384]/10" /></label><button disabled={!canSubmit} onClick={onSubmit} className="mt-4 inline-flex items-center gap-2 rounded-xl bg-[#0E9384] px-4 py-2.5 text-xs font-extrabold text-white transition hover:bg-[#087A6D] active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-50">{isBusy ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}{updateToday ? "Save changes" : "Submit update"}</button></section><section className="rounded-2xl border border-[#E1EAED] bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><div><p className="text-[10px] font-extrabold uppercase tracking-[0.15em] text-[#0E9384]">Work history</p><h2 className="mt-1 text-lg font-extrabold">Your submitted updates</h2></div><span className="rounded-full bg-[#F3F7F8] px-2.5 py-1 text-[10px] font-extrabold text-[#658092]">{updates.length} total</span></div><div className="mt-4 space-y-3">{updates.length ? updates.map((update) => <article key={update.id} className="rounded-xl border border-[#E6EEF0] p-3.5"><div className="flex items-center justify-between gap-3"><p className="text-xs font-extrabold">{formatDate(update.updateDate)}</p><span className="text-xs font-extrabold text-[#0E9384]">{duration(update.totalMinutes)}</span></div><ul className="mt-2.5 space-y-1.5">{update.tasks.map((task) => <li key={task.id} className="flex justify-between gap-3 text-xs font-medium text-[#647B8C]"><span>{task.description}</span><span className="shrink-0 text-[#8A9AA7]">{duration(task.minutes)}</span></li>)}</ul>{update.blockers && <p className="mt-2.5 border-t border-[#EFF3F5] pt-2.5 text-xs font-medium leading-5 text-[#9B6943]">Blocker: {update.blockers}</p>}</article>) : <Empty icon={ClipboardList} title="No updates submitted" detail="Your real work history will appear here after your first submission." />}</div></section></div><section className="rounded-2xl border border-[#E1EAED] bg-white p-5 shadow-sm"><p className="text-[10px] font-extrabold uppercase tracking-[0.15em] text-[#0E9384]">Assigned tasks</p><h2 className="mt-1 text-lg font-extrabold">Your active queue</h2><div className="mt-4 space-y-3">{tasks.length ? tasks.map((task) => <article key={task.id} className={`rounded-xl border p-3.5 ${task.status === "completed" ? "border-[#DBECE8] bg-[#F6FCFA]" : "border-[#E6EEF0]"}`}><div className="flex gap-3"><button aria-label="Complete task" disabled={task.status === "completed" || isBusy} onClick={() => onComplete(task.id)} className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border ${task.status === "completed" ? "border-[#0E9384] bg-[#0E9384] text-white" : "border-[#B9CBD3] text-transparent hover:border-[#0E9384]"}`}><Check className="h-3 w-3" /></button><div className="min-w-0 flex-1"><p className={`text-xs font-extrabold leading-5 ${task.status === "completed" ? "text-[#7B919C] line-through" : "text-[#294354]"}`}>{task.description}</p><p className="mt-1 text-[10px] font-semibold text-[#8A9AA7]">Assigned {new Date(task.assignedAt).toLocaleDateString()}</p>{task.remarks.length > 0 && <p className="mt-2 text-[11px] font-medium text-[#718695]">{task.remarks.length} remark{task.remarks.length === 1 ? "" : "s"}</p>}</div></div></article>) : <Empty icon={CheckCircle2} title="No assigned tasks" detail="Tasks assigned by a Manager or Admin will appear in this live queue." />}</div></section></div>;
}

function TeamUpdates({ workDate, setWorkDate, members }: { workDate: string; setWorkDate: (date: string) => void; members: TeamMember[] }) { const submitted = members.filter((member) => member.update); return <div className="space-y-5"><section className="flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-[#E1EAED] bg-white p-4 shadow-sm"><div><p className="text-[10px] font-extrabold uppercase tracking-[0.15em] text-[#0E9384]">Compliance view</p><p className="mt-1 text-sm font-extrabold">{submitted.length} submitted · {members.length - submitted.length} pending</p></div><label className="flex items-center gap-2 rounded-xl border border-[#DDE7EB] px-3 py-2 text-xs font-extrabold text-[#627A8B]"><Clock3 className="h-3.5 w-3.5" /><input type="date" value={workDate} onChange={(event) => setWorkDate(event.target.value)} className="bg-transparent outline-none" /></label></section><section className="overflow-hidden rounded-2xl border border-[#E1EAED] bg-white shadow-sm"><div className="grid grid-cols-[minmax(180px,1.15fr)_90px_minmax(200px,1.6fr)] gap-4 border-b border-[#EAF0F2] bg-[#F8FAFB] px-5 py-3 text-[9px] font-extrabold uppercase tracking-[0.12em] text-[#7890A0]"><span>Developer</span><span>Status</span><span>Tasks summary</span></div>{members.length ? members.map(({ user, update }) => <div key={user.id} className="grid grid-cols-[minmax(180px,1.15fr)_90px_minmax(200px,1.6fr)] gap-4 border-b border-[#EEF3F5] px-5 py-4 last:border-b-0"><div className="flex min-w-0 items-center gap-3"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-[#EAF7F4] text-[10px] font-extrabold text-[#087A6D]">{initials(user.displayName, user.email)}</span><div className="min-w-0"><p className="truncate text-xs font-extrabold">{user.displayName || user.email}</p><p className="truncate text-[10px] font-medium text-[#8494A0]">{user.email}</p></div></div><span className={`my-auto w-fit rounded-full px-2 py-1 text-[9px] font-extrabold uppercase tracking-[0.08em] ${update ? "bg-[#EAF7F4] text-[#087A6D]" : "bg-[#F2F5F6] text-[#7E909C]"}`}>{update ? "Submitted" : "Pending"}</span><div className="min-w-0">{update ? <><p className="text-xs font-extrabold text-[#0E9384]">{duration(update.totalMinutes)}</p><p className="mt-1 truncate text-xs font-medium text-[#637A8A]">{update.tasks.map((task) => task.description).join(" · ")}</p>{update.blockers && <p className="mt-1 text-[10px] font-semibold text-[#9C6B45]">Blocker: {update.blockers}</p>}</> : <p className="pt-1 text-xs font-medium text-[#96A5AE]">No update for this date</p>}</div></div>) : <div className="p-6"><Empty icon={UsersRound} title="No employees yet" detail="Approved Google sign-ins create real employee records in this team view." /></div>}</section></div>; }

function AttendanceView({ attendance }: { attendance: Attendance | null }) { return <section className="max-w-2xl rounded-2xl border border-[#E1EAED] bg-white p-6 shadow-sm"><p className="text-[10px] font-extrabold uppercase tracking-[0.15em] text-[#0E9384]">Today’s attendance</p><h2 className="mt-1 text-xl font-extrabold">Your live punch record</h2>{attendance ? <div className="mt-5 grid gap-3 sm:grid-cols-3"><Metric label="Status" value={attendance.classification === "on_time" ? "On time" : "Late"} tone={attendance.classification === "on_time" ? "teal" : "amber"} /><Metric label="Punch in" value={formatTime(attendance.punchInAt)} /><Metric label="Punch out" value={formatTime(attendance.punchOutAt)} /></div> : <div className="mt-5"><Empty icon={CalendarCheck2} title="No punch recorded" detail="Use the Punch in control above to create today’s real attendance record." /></div>}<div className="mt-5 rounded-xl border border-[#E5EDF0] bg-[#F8FBFC] p-3"><p className="text-[11px] font-semibold leading-5 text-[#708492]">Office hours are currently **9:00 AM–6:30 PM IST**. Punches up to 9:15 AM are classified as On Time; later punches are marked Late.</p></div></section>; }

function RoleManagement({ users, selfId, isBusy, onChangeRole }: { users: User[]; selfId: string; isBusy: boolean; onChangeRole: (id: string, role: Role) => void }) { return <section className="overflow-hidden rounded-2xl border border-[#E1EAED] bg-white shadow-sm"><div className="border-b border-[#EAF0F2] px-5 py-4"><p className="text-[10px] font-extrabold uppercase tracking-[0.15em] text-[#0E9384]">Server-authorized access</p><h2 className="mt-1 text-lg font-extrabold">Manage team roles</h2><p className="mt-1 text-xs font-medium text-[#718494]">Role changes are persistent, audited, and only available to an Admin.</p></div>{users.length ? <div className="divide-y divide-[#EEF3F5]">{users.map((member) => <div key={member.id} className="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><div className="flex min-w-0 items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-full bg-[#EAF7F4] text-[10px] font-extrabold text-[#087A6D]">{initials(member.displayName, member.email)}</span><div className="min-w-0"><p className="truncate text-xs font-extrabold">{member.displayName || member.email}{member.id === selfId && " (you)"}</p><p className="truncate text-[10px] font-medium text-[#8494A0]">{member.email}</p></div></div><label className="flex items-center gap-2 text-[10px] font-extrabold uppercase tracking-[0.1em] text-[#7D909D]"><span>Role</span><select disabled={isBusy || member.email === "anurag.xitijinfo@gmail.com"} value={member.role} onChange={(event) => onChangeRole(member.id, event.target.value as Role)} className="rounded-lg border border-[#DCE7EA] bg-white px-2 py-1.5 text-xs font-extrabold normal-case tracking-normal text-[#294354] outline-none focus:border-[#0E9384] disabled:cursor-not-allowed disabled:opacity-60"><option value="developer">Developer</option><option value="manager">Manager</option><option value="admin">Admin</option></select></label></div>)}</div> : <div className="p-6"><Empty icon={Crown} title="No users yet" detail="The first verified Google sign-in will create the initial Admin record here." /></div>}</section>; }

function NotificationDrawer({ notifications, onClose, onMarkRead }: { notifications: Notification[]; onClose: () => void; onMarkRead: (id?: string) => void }) { return <div className="fixed inset-0 z-50 bg-[#173247]/20 backdrop-blur-[1px]" onMouseDown={onClose}><aside onMouseDown={(event) => event.stopPropagation()} className="absolute right-0 top-0 flex h-full w-full max-w-sm flex-col bg-white shadow-2xl"><div className="flex items-center justify-between border-b border-[#E5EDF0] p-5"><div><p className="text-[10px] font-extrabold uppercase tracking-[0.14em] text-[#0E9384]">Signal center</p><h2 className="mt-1 text-lg font-extrabold">Notifications</h2></div><button onClick={onClose} className="rounded-lg p-2 text-[#6C8291] hover:bg-[#F3F7F8]"><X className="h-4 w-4" /></button></div>{notifications.some((notification) => !notification.isRead) && <button onClick={() => onMarkRead()} className="mx-5 mt-4 self-start text-xs font-extrabold text-[#0E9384] hover:text-[#087A6D]">Mark all as read</button>}<div className="flex-1 overflow-y-auto p-5">{notifications.length ? <div className="space-y-3">{notifications.map((notification) => <article key={notification.id} className={`rounded-xl border p-3.5 ${notification.isRead ? "border-[#E9EFF1]" : "border-[#D8ECE8] bg-[#F7FCFA]"}`}><div className="flex gap-2"><span className="mt-1 h-2 w-2 shrink-0 rounded-full bg-[#0E9384]" /><div className="min-w-0 flex-1"><p className="text-xs font-extrabold">{notification.title}</p><p className="mt-1 text-xs font-medium leading-5 text-[#708494]">{notification.body}</p><div className="mt-2 flex items-center justify-between gap-2"><span className="text-[10px] font-semibold text-[#92A1AA]">{new Date(notification.createdAt).toLocaleString()}</span>{!notification.isRead && <button onClick={() => onMarkRead(notification.id)} className="text-[10px] font-extrabold text-[#0E9384]">Mark read</button>}</div></div></div></article>)}</div> : <Empty icon={Bell} title="No notifications" detail="Task and role activity will appear here as it happens." />}</div></aside></div>; }

function Metric({ label, value, tone }: { label: string; value: string; tone?: "teal" | "amber" }) { return <div className="rounded-xl border border-[#E5EDF0] p-3"><p className="text-[9px] font-extrabold uppercase tracking-[0.12em] text-[#8B9BA6]">{label}</p><p className={`mt-1 text-sm font-extrabold ${tone === "teal" ? "text-[#0E9384]" : tone === "amber" ? "text-[#A87532]" : "text-[#294354]"}`}>{value}</p></div>; }
function Empty({ icon: Icon, title, detail }: { icon: typeof ClipboardList; title: string; detail: string }) { return <div className="rounded-xl border border-dashed border-[#DDE7EA] bg-[#FBFCFD] px-4 py-8 text-center"><span className="mx-auto flex h-9 w-9 items-center justify-center rounded-xl bg-[#EAF7F4] text-[#0E9384]"><Icon className="h-4 w-4" /></span><p className="mt-3 text-xs font-extrabold text-[#486170]">{title}</p><p className="mx-auto mt-1 max-w-xs text-[11px] font-medium leading-5 text-[#8294A0]">{detail}</p></div>; }
function LoadingState() { return <div className="flex min-h-80 items-center justify-center rounded-2xl border border-[#E2EAED] bg-white"><LoaderCircle className="h-5 w-5 animate-spin text-[#0E9384]" /></div>; }

function MyUpdatesV2({ attendance, businessDate, workDate, setWorkDate, update, updates, tasks, draftTasks, blockers, remarkText, isBusy, onDraftTasks, onBlockers, onRemarkText, onSubmit, onComplete, onAddRemark }: { attendance: Attendance | null; businessDate: string; workDate: string; setWorkDate: (value: string) => void; update: WorkUpdate | null; updates: WorkUpdate[]; tasks: AssignedTask[]; draftTasks: { id: string; description: string; minutes: string }[]; blockers: string; remarkText: Record<string, string>; isBusy: boolean; onDraftTasks: (value: { id: string; description: string; minutes: string }[]) => void; onBlockers: (value: string) => void; onRemarkText: (value: Record<string, string>) => void; onSubmit: () => void; onComplete: (id: string) => void; onAddRemark: (id: string) => void }) {
  const yesterday = new Date(`${businessDate}T12:00:00Z`); yesterday.setUTCDate(yesterday.getUTCDate() - 1); const yesterdayKey = yesterday.toISOString().slice(0, 10);
  const canSubmit = Boolean(attendance && draftTasks.length && draftTasks.every((task) => task.description.trim() && Number(task.minutes) >= 0) && !isBusy);
  function updateDraft(index: number, field: "description" | "minutes", value: string) { onDraftTasks(draftTasks.map((task, taskIndex) => taskIndex === index ? { ...task, [field]: field === "minutes" ? value.replace(/[^0-9]/g, "") : value } : task)); }
  return <div className="grid gap-5 xl:grid-cols-[1.12fr_0.88fr]"><div className="space-y-5"><section className="rounded-2xl border border-[#E1EAED] bg-white p-5 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[10px] font-extrabold uppercase tracking-[0.15em] text-[#0E9384]">Daily work update</p><h2 className="mt-1 text-lg font-extrabold">{update ? "Edit your submitted work" : "Log what you completed"}</h2></div><label className="rounded-xl border border-[#DDE7EB] px-2.5 py-1.5 text-xs font-extrabold text-[#627A8B]"><select value={workDate} onChange={(event) => setWorkDate(event.target.value)} className="bg-transparent outline-none"><option value={businessDate}>Today · {formatDate(businessDate)}</option><option value={yesterdayKey}>Yesterday · {formatDate(yesterdayKey)}</option></select></label></div>{!attendance && workDate === businessDate && <div className="mt-4 rounded-xl border border-[#F2DFC0] bg-[#FFF9EF] px-3 py-2.5 text-xs font-semibold text-[#946D2B]">Punch In Required — punch in today before submitting today’s work update.</div>}<div className="mt-5 space-y-3">{draftTasks.map((task, index) => <div key={task.id} className="grid gap-2 rounded-xl border border-[#E4ECEF] bg-[#FBFCFD] p-3 sm:grid-cols-[1fr_100px_auto]"><input value={task.description} onChange={(event) => updateDraft(index, "description", event.target.value)} placeholder={`Task ${index + 1} completed`} className="rounded-lg border border-[#DDE7EB] bg-white px-3 py-2 text-sm font-semibold outline-none focus:border-[#0E9384]" /><input value={task.minutes} onChange={(event) => updateDraft(index, "minutes", event.target.value)} inputMode="numeric" aria-label={`Minutes for task ${index + 1}`} className="rounded-lg border border-[#DDE7EB] bg-white px-3 py-2 text-sm font-semibold outline-none focus:border-[#0E9384]" />{draftTasks.length > 1 ? <button onClick={() => onDraftTasks(draftTasks.filter((_, taskIndex) => taskIndex !== index))} className="rounded-lg px-2 text-xs font-extrabold text-[#A64D43] hover:bg-[#FFF2F0]">Remove</button> : <span />}</div>)}</div><button onClick={() => onDraftTasks([...draftTasks, { id: crypto.randomUUID(), description: "", minutes: "0" }])} className="mt-3 inline-flex items-center gap-1.5 text-xs font-extrabold text-[#0E9384] hover:text-[#087A6D]"><Plus className="h-3.5 w-3.5" />Add another task</button><label className="mt-4 block"><span className="mb-1.5 block text-[10px] font-extrabold uppercase tracking-[0.11em] text-[#7890A0]">Blockers / notes <span className="normal-case tracking-normal">(optional)</span></span><textarea value={blockers} onChange={(event) => onBlockers(event.target.value)} placeholder="Detailed blockers or issues your team should know" rows={3} className="w-full resize-none rounded-xl border border-[#DDE7EB] px-3 py-2.5 text-sm font-medium outline-none focus:border-[#0E9384]" /></label><button disabled={!canSubmit} onClick={onSubmit} className="mt-4 inline-flex items-center gap-2 rounded-xl bg-[#0E9384] px-4 py-2.5 text-xs font-extrabold text-white transition hover:bg-[#087A6D] active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-50">{isBusy ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}{update ? "Save changes" : "Submit update"}</button></section><section className="rounded-2xl border border-[#E1EAED] bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><div><p className="text-[10px] font-extrabold uppercase tracking-[0.15em] text-[#0E9384]">Work history</p><h2 className="mt-1 text-lg font-extrabold">Your submitted updates</h2></div><span className="rounded-full bg-[#F3F7F8] px-2.5 py-1 text-[10px] font-extrabold text-[#658092]">{updates.length} total</span></div><div className="mt-4 space-y-3">{updates.length ? updates.map((history) => <article key={history.id} className="rounded-xl border border-[#E6EEF0] p-3.5"><div className="flex items-center justify-between gap-3"><p className="text-xs font-extrabold">{formatDate(history.updateDate)}</p><span className="text-xs font-extrabold text-[#0E9384]">{duration(history.totalMinutes)}</span></div><ul className="mt-2.5 space-y-1.5">{history.tasks.map((task) => <li key={task.id} className="flex justify-between gap-3 text-xs font-medium text-[#647B8C]"><span>{task.description}</span><span className="shrink-0 text-[#8A9AA7]">{duration(task.minutes)}</span></li>)}</ul>{history.blockers && <p className="mt-2.5 border-t border-[#EFF3F5] pt-2.5 text-xs font-medium leading-5 text-[#9B6943]">Blocker: {history.blockers}</p>}</article>) : <Empty icon={ClipboardList} title="No updates submitted" detail="Your real work history appears after your first submission." />}</div></section></div><section className="rounded-2xl border border-[#E1EAED] bg-white p-5 shadow-sm"><p className="text-[10px] font-extrabold uppercase tracking-[0.15em] text-[#0E9384]">Assigned tasks</p><h2 className="mt-1 text-lg font-extrabold">Your active queue</h2><div className="mt-4 space-y-3">{tasks.length ? tasks.map((task) => <article key={task.id} className={`rounded-xl border p-3.5 ${task.status === "completed" ? "border-[#DBECE8] bg-[#F6FCFA]" : "border-[#E6EEF0]"}`}><div className="flex gap-3"><button aria-label="Complete task" disabled={task.status === "completed" || isBusy} onClick={() => onComplete(task.id)} className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border ${task.status === "completed" ? "border-[#0E9384] bg-[#0E9384] text-white" : "border-[#B9CBD3] text-transparent hover:border-[#0E9384]"}`}><Check className="h-3 w-3" /></button><div className="min-w-0 flex-1"><p className={`text-xs font-extrabold leading-5 ${task.status === "completed" ? "text-[#7B919C] line-through" : "text-[#294354]"}`}>{task.description}</p><p className="mt-1 text-[10px] font-semibold text-[#8A9AA7]">Assigned {new Date(task.assignedAt).toLocaleDateString()}</p>{task.remarks.length > 0 && <div className="mt-2 space-y-1.5">{task.remarks.map((remark) => <p key={remark.id} className="rounded-lg bg-white/80 px-2 py-1.5 text-[10px] font-medium text-[#6E8190]"><strong>{remark.userName}:</strong> {remark.text}</p>)}</div>}<div className="mt-3 flex gap-2"><input value={remarkText[task.id] || ""} onChange={(event) => onRemarkText({ ...remarkText, [task.id]: event.target.value })} placeholder="Add a remark…" className="min-w-0 flex-1 rounded-lg border border-[#DDE7EB] bg-white px-2.5 py-1.5 text-[11px] font-medium outline-none focus:border-[#0E9384]" /><button disabled={isBusy || !(remarkText[task.id] || "").trim()} onClick={() => onAddRemark(task.id)} className="rounded-lg bg-[#EAF7F4] px-2.5 text-[10px] font-extrabold text-[#087A6D] disabled:opacity-50">Send</button></div></div></div></article>) : <Empty icon={CheckCircle2} title="No assigned tasks" detail="Tasks assigned by a Manager or Admin appear in this live queue." />}</div></section></div>;
}

function TeamUpdatesV2({ workDate, setWorkDate, members }: { workDate: string; setWorkDate: (value: string) => void; members: TeamMember[] }) {
  const [view, setView] = useState<"list" | "grid">("list"); const [developerUserId, setDeveloperUserId] = useState(""); const [description, setDescription] = useState(""); const [isAssigning, setIsAssigning] = useState(false); const [assignmentMessage, setAssignmentMessage] = useState<string | null>(null);
  const submitted = members.filter((member) => member.update).length;
  async function assign() { setIsAssigning(true); setAssignmentMessage(null); try { await request("/api/tasks", { method: "POST", body: JSON.stringify({ developerUserId, description }) }); setDescription(""); setAssignmentMessage("Task assigned and a notification was created."); } catch (error) { setAssignmentMessage(error instanceof Error ? error.message : "Task could not be assigned."); } finally { setIsAssigning(false); } }
  return <div className="space-y-5"><section className="rounded-2xl border border-[#E1EAED] bg-white p-4 shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-[10px] font-extrabold uppercase tracking-[0.15em] text-[#0E9384]">Compliance view</p><p className="mt-1 text-sm font-extrabold">{submitted} submitted · {members.length - submitted} pending</p></div><div className="flex items-center gap-2"><div className="flex rounded-lg bg-[#F2F6F7] p-1"><button onClick={() => setView("list")} className={`rounded-md px-2 py-1.5 text-[10px] font-extrabold ${view === "list" ? "bg-white text-[#173247] shadow-sm" : "text-[#7B8D99]"}`}>List</button><button onClick={() => setView("grid")} className={`rounded-md px-2 py-1.5 text-[10px] font-extrabold ${view === "grid" ? "bg-white text-[#173247] shadow-sm" : "text-[#7B8D99]"}`}>Grid</button></div><label className="flex items-center gap-2 rounded-xl border border-[#DDE7EB] px-3 py-2 text-xs font-extrabold text-[#627A8B]"><Clock3 className="h-3.5 w-3.5" /><input type="date" value={workDate} onChange={(event) => setWorkDate(event.target.value)} className="bg-transparent outline-none" /></label></div></div></section><section className="rounded-2xl border border-[#E1EAED] bg-white p-5 shadow-sm"><p className="text-[10px] font-extrabold uppercase tracking-[0.15em] text-[#0E9384]">Assign new task</p><div className="mt-3 grid gap-2 md:grid-cols-[220px_1fr_auto]"><select value={developerUserId} onChange={(event) => setDeveloperUserId(event.target.value)} className="rounded-xl border border-[#DDE7EB] bg-white px-3 py-2.5 text-xs font-extrabold outline-none focus:border-[#0E9384]"><option value="">Select employee</option>{members.map(({ user }) => <option key={user.id} value={user.id}>{user.displayName || user.email}</option>)}</select><input value={description} onChange={(event) => setDescription(event.target.value)} placeholder="What needs to be done?" className="rounded-xl border border-[#DDE7EB] px-3 py-2.5 text-sm font-medium outline-none focus:border-[#0E9384]" /><button disabled={isAssigning || !developerUserId || description.trim().length < 3} onClick={assign} className="rounded-xl bg-[#173247] px-4 py-2.5 text-xs font-extrabold text-white disabled:cursor-not-allowed disabled:opacity-50">{isAssigning ? "Assigning…" : "Assign task"}</button></div>{assignmentMessage && <p className="mt-2 text-xs font-semibold text-[#0E9384]">{assignmentMessage}</p>}</section>{view === "list" ? <section className="overflow-hidden rounded-2xl border border-[#E1EAED] bg-white shadow-sm"><div className="grid grid-cols-[minmax(180px,1.15fr)_90px_minmax(200px,1.6fr)] gap-4 border-b border-[#EAF0F2] bg-[#F8FAFB] px-5 py-3 text-[9px] font-extrabold uppercase tracking-[0.12em] text-[#7890A0]"><span>Developer</span><span>Status</span><span>Tasks summary</span></div>{members.map(({ user, update }) => <div key={user.id} className="grid grid-cols-[minmax(180px,1.15fr)_90px_minmax(200px,1.6fr)] gap-4 border-b border-[#EEF3F5] px-5 py-4 last:border-b-0"><div className="flex min-w-0 items-center gap-3"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-[#EAF7F4] text-[10px] font-extrabold text-[#087A6D]">{initials(user.displayName, user.email)}</span><div className="min-w-0"><p className="truncate text-xs font-extrabold">{user.displayName || user.email}</p><p className="truncate text-[10px] font-medium text-[#8494A0]">{user.email}</p></div></div><span className={`my-auto w-fit rounded-full px-2 py-1 text-[9px] font-extrabold uppercase tracking-[0.08em] ${update ? "bg-[#EAF7F4] text-[#087A6D]" : "bg-[#F2F5F6] text-[#7E909C]"}`}>{update ? "Submitted" : "Pending"}</span><div className="min-w-0">{update ? <><p className="text-xs font-extrabold text-[#0E9384]">{duration(update.totalMinutes)}</p><p className="mt-1 truncate text-xs font-medium text-[#637A8A]">{update.tasks.map((task) => task.description).join(" · ")}</p>{update.blockers && <p className="mt-1 text-[10px] font-semibold text-[#9C6B45]">Blocker: {update.blockers}</p>}</> : <p className="pt-1 text-xs font-medium text-[#96A5AE]">No update for this date</p>}</div></div>)}</section> : <section className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{members.map(({ user, update }) => <article key={user.id} className="rounded-2xl border border-[#E1EAED] bg-white p-5 shadow-sm"><div className="flex items-center gap-3"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-[#EAF7F4] text-xs font-extrabold text-[#087A6D]">{initials(user.displayName, user.email)}</span><div className="min-w-0"><p className="truncate text-sm font-extrabold">{user.displayName || user.email}</p><p className="truncate text-[10px] font-medium text-[#8797A2]">{user.email}</p></div></div><span className={`mt-5 inline-flex rounded-full px-2 py-1 text-[9px] font-extrabold uppercase tracking-[0.08em] ${update ? "bg-[#EAF7F4] text-[#087A6D]" : "bg-[#F2F5F6] text-[#7E909C]"}`}>{update ? "Submitted" : "Pending"}</span><p className="mt-4 text-xs font-medium leading-5 text-[#718493]">{update ? update.tasks.map((task) => task.description).join(" · ") : "No update submitted for this date."}</p>{update && <p className="mt-3 text-xs font-extrabold text-[#0E9384]">{duration(update.totalMinutes)}</p>}</article>)}</section>}</div>;
}

function AttendanceModule({ attendance, businessDate, canViewTeam }: { attendance: Attendance | null; businessDate: string; canViewTeam: boolean }) {
  const [workDate, setWorkDate] = useState(businessDate); const [rows, setRows] = useState<{ user: User; attendance: Attendance | null }[]>([]); const [loading, setLoading] = useState(false); const [hasLoaded, setHasLoaded] = useState(false); const [error, setError] = useState<string | null>(null);
  const load = useCallback(async () => { if (!canViewTeam) return; if (!hasLoaded) setLoading(true); try { setRows((await request<{ rows: { user: User; attendance: Attendance | null }[] }>(`/api/team-attendance?workDate=${workDate}`)).rows); setError(null); } catch (loadError) { setError(loadError instanceof Error ? loadError.message : "Unable to load team attendance."); } finally { setLoading(false); setHasLoaded(true); } }, [canViewTeam, hasLoaded, workDate]);
  useEffect(() => { void load(); }, [load]);
  useEffect(() => { if (!canViewTeam) return; const timer = window.setInterval(() => { void load(); }, 15_000); return () => window.clearInterval(timer); }, [canViewTeam, load]);
  if (!canViewTeam) return <AttendanceView attendance={attendance} />;
  const present = rows.filter((row) => row.attendance).length;
  return <section className="overflow-hidden rounded-2xl border border-[#E1EAED] bg-white shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#EAF0F2] p-5"><div><p className="text-[10px] font-extrabold uppercase tracking-[0.15em] text-[#0E9384]">Team attendance</p><h2 className="mt-1 text-lg font-extrabold">{present} present · {rows.length - present} absent</h2><p className="mt-1 text-xs font-medium text-[#718494]">Office hours: 9:00 AM–6:30 PM IST; on-time grace ends 9:15 AM.</p></div><label className="rounded-xl border border-[#DDE7EB] px-3 py-2 text-xs font-extrabold text-[#627A8B]"><input type="date" value={workDate} onChange={(event) => setWorkDate(event.target.value)} className="bg-transparent outline-none" /></label></div>{error && <p className="m-5 rounded-xl bg-[#FFF5F4] p-3 text-xs font-semibold text-[#A64D43]">{error}</p>}{loading ? <div className="p-8"><LoadingState /></div> : <div className="overflow-x-auto"><div className="min-w-[720px]"><div className="grid grid-cols-[1.2fr_100px_110px_110px_1.3fr] gap-3 border-b border-[#EAF0F2] bg-[#F8FAFB] px-5 py-3 text-[9px] font-extrabold uppercase tracking-[0.12em] text-[#7890A0]"><span>Team member</span><span>Status</span><span>Punch in</span><span>Punch out</span><span>Device / IP</span></div>{rows.map(({ user, attendance: record }) => <div key={user.id} className="grid grid-cols-[1.2fr_100px_110px_110px_1.3fr] gap-3 border-b border-[#EEF3F5] px-5 py-4 last:border-b-0"><div className="flex min-w-0 items-center gap-2.5"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-[#EAF7F4] text-[10px] font-extrabold text-[#087A6D]">{initials(user.displayName, user.email)}</span><div className="min-w-0"><p className="truncate text-xs font-extrabold">{user.displayName || user.email}</p><p className="truncate text-[10px] font-medium text-[#8494A0]">{user.email}</p></div></div><span className={`my-auto w-fit rounded-full px-2 py-1 text-[9px] font-extrabold uppercase tracking-[0.08em] ${record ? record.classification === "on_time" ? "bg-[#EAF7F4] text-[#087A6D]" : "bg-[#FFF5E7] text-[#A87532]" : "bg-[#F2F5F6] text-[#7E909C]"}`}>{record ? record.classification === "on_time" ? "On time" : "Late" : "Absent"}</span><span className="my-auto text-xs font-semibold text-[#536D7E]">{formatTime(record?.punchInAt)}</span><span className="my-auto text-xs font-semibold text-[#536D7E]">{formatTime(record?.punchOutAt)}</span><span className="my-auto truncate text-[10px] font-medium text-[#7D909D]" title={record?.device.userAgent || undefined}>{record?.device.ipAddress || "—"}{record?.device.userAgent ? " · browser recorded" : ""}</span></div>)}</div></div>}</section>;
}
